INSERT INTO public.immigration_changes (id, country, country_code, flag, visa_type, category, title, description, long_description, previous_rule, new_rule, effective_date, announcement_date, source_url, source_name, status, impact, reviewed_by, key_points) VALUES
('uk-grad-dep-2026', 'United Kingdom', 'UK', '🇬🇧', 'Graduate Route', 'Family', 'Dependants rule updated for UK-born children', 'Children born in the UK to parents holding Graduate route permission can now apply as dependants.', 'A notable change allows children born in the UK to parents holding Graduate route permission to apply as dependants in line with their parent. This application must be made within the UK to ensure family unity during the post-study work period.', 'No specific provision for UK-born children to apply in-country as dependants under this route.', 'Children born in the UK to Graduate route holders can apply as dependants from within the UK.', '2026-08-03', '2026-07-15', 'https://www.gov.uk/graduate-visa', 'Home Office', 'approved', 'Families on Graduate Route', 'Radar Editorial', '{"Applies only to children born in the UK.", "Application must be made from within the UK.", "Aligns expiry with the parent''s visa."}'),
('uk-crim-2026', 'United Kingdom', 'UK', '🇬🇧', 'All Visas', 'Compliance', 'Stricter criminality rules enforced', 'Custodial or suspended sentences of 12 months or more lead to mandatory refusal or cancellation.', 'The Home Office has tightened the rules regarding criminality. Individuals convicted in the UK and given a custodial or suspended sentence of 12 months or more face mandatory refusal or cancellation of their permission to stay.', 'Discretionary refusal based on various factors for some sentences.', 'Mandatory refusal or cancellation for 12+ month custodial/suspended sentences.', '2026-03-26', '2026-02-10', 'https://www.gov.uk/guidance/immigration-rules/immigration-rules-part-9-grounds-for-refusal', 'Home Office', 'urgent', 'All visa holders and applicants', 'Radar Editorial', '{"Applies to both custodial and suspended sentences.", "Threshold set at 12 months.", "Mandatory cancellation of existing permission."}'),
('uk-bail-2026', 'United Kingdom', 'UK', '🇬🇧', 'Family and Human Rights', 'Compliance', 'Exception for overstayers adjusted', 'Adjustments to ensure those under "Exception for Overstayers" aren''t refused solely due to immigration bail.', 'Adjustments were made to ensure that individuals applying under the "Exception for Overstayers" provision are not refused solely on the grounds of being on immigration bail, protecting vulnerable applicants.', 'Being on immigration bail could lead to refusal even if an exception applied.', 'Immigration bail alone is not a ground for refusal under the overstayer exception.', '2026-08-03', '2026-07-15', 'https://www.gov.uk/guidance/immigration-rules', 'Home Office', 'info', 'Overstayers and asylum seekers', 'Radar Editorial', '{"Protects individuals on immigration bail.", "Applies to specific exception categories.", "Promotes fairer decision-making."}'),
('uk-eta-2026', 'United Kingdom', 'UK', '🇬🇧', 'ETA', 'Border Entry', 'Mandatory permission-to-travel checks', 'Carriers must conduct mandatory automated checks before boarding.', 'The UK has moved toward stricter border enforcement. Carriers (airlines, ferry, and rail operators) are required to conduct mandatory permission-to-travel checks using automated systems before allowing passengers to board.', 'Manual checks or less strict automated enforcement.', 'Strict automated permission-to-travel checks mandatory for all carriers.', '2026-02-25', '2025-11-20', 'https://www.gov.uk/guidance/electronic-travel-authorisation-eta', 'Home Office', 'warning', 'All incoming travellers without a visa', 'Radar Editorial', '{"Applies to airlines, ferries, and rail.", "Requires valid digital status or ETA.", "Passengers without permission will be denied boarding."}'),
('uk-isc-2026', 'United Kingdom', 'UK', '🇬🇧', 'Skilled Worker', 'Employment', 'Immigration Skills Charge increased', 'The Immigration Skills Charge (ISC) has seen a 32% increase for both large and small sponsors.', 'To help manage the sponsorship regime and fund domestic skills development, the Immigration Skills Charge saw a significant increase (32%) for both large and small sponsors.', 'Lower ISC fees for sponsors.', '32% increase in ISC fees for all sponsor sizes.', '2026-01-01', '2025-10-15', 'https://www.gov.uk/uk-visa-sponsorship-employers/immigration-skills-charge', 'Home Office', 'urgent', 'UK Employers and Sponsors', 'Radar Editorial', '{"32% increase applied to all tiers.", "Affects new Certificate of Sponsorship (CoS) assignments.", "Aims to fund domestic workforce training."}'),
('uk-gt-design-2026', 'United Kingdom', 'UK', '🇬🇧', 'Global Talent', 'Employment', 'Design endorsement pathway introduced', 'The Global Talent category was broadened to include a specific design endorsement pathway.', 'The Global Talent visa category has been expanded to better attract top creative talent, specifically broadening the criteria to include a dedicated design endorsement pathway for exceptional designers.', 'Designers had to fit into broader, less specific creative categories.', 'Dedicated design endorsement pathway available.', '2026-04-06', '2026-03-01', 'https://www.gov.uk/global-talent-visa', 'Home Office', 'approved', 'Design professionals', 'Radar Editorial', '{"New dedicated pathway for designers.", "Endorsed by recognized arts and culture bodies.", "Standard Global Talent benefits apply."}'),
('uk-dip-2026', 'United Kingdom', 'UK', '🇬🇧', 'Visitor Visa', 'Diplomatic', 'Diplomatic Visa Arrangement extended', 'The Diplomatic Visa Arrangement for visitor visas now includes eligible Indian diplomatic passport holders.', 'The UK has extended its Diplomatic Visa Arrangement for visitor visas to include eligible Indian diplomatic passport holders, streamlining the process for official visits and strengthening bilateral ties.', 'Indian diplomatic passport holders required standard visa processing.', 'Included in the Diplomatic Visa Arrangement for streamlined processing.', '2026-08-03', '2026-07-15', 'https://www.gov.uk/guidance/immigration-rules', 'Home Office', 'info', 'Indian diplomats', 'Radar Editorial', '{"Applies to Indian diplomatic passport holders.", "Streamlined visitor visa process.", "Strengthens diplomatic relations."}'),
('uk-evisa-2026', 'United Kingdom', 'UK', '🇬🇧', 'All Visas', 'Compliance', 'Complete transition to eVisas enforced', 'Physical BRPs and vignette stickers are now fully phased out in favor of digital eVisas.', 'Following the phase-out plan, the Home Office has officially mandated that all individuals must use their digital immigration status (eVisa). Physical Biometric Residence Permits (BRPs) and passport vignettes are no longer valid for proving status.', 'Physical BRPs and vignettes used as primary proof of status.', 'Digital eVisas are the sole accepted proof of immigration status.', '2026-01-01', '2025-06-01', 'https://www.gov.uk/guidance/online-immigration-status-evisa', 'Home Office', 'urgent', 'All visa holders in the UK', 'Radar Editorial', '{"Physical BRPs are no longer valid.", "Must register for a UKVI account.", "Status is proven entirely online."}'),
('uk-swv-salary-2026', 'United Kingdom', 'UK', '🇬🇧', 'Skilled Worker', 'Employment', 'Minimum salary thresholds adjusted', 'Skilled Worker visa minimum salary thresholds and going rates updated to latest ASHE data.', 'The Home Office has updated the minimum salary thresholds and occupation-specific going rates for the Skilled Worker route, aligning them with the latest Annual Survey of Hours and Earnings (ASHE) data to ensure wage parity.', 'Older ASHE data used for going rates.', 'Latest ASHE data dictates higher going rates and baseline thresholds.', '2026-04-04', '2026-03-14', 'https://www.gov.uk/skilled-worker-visa/your-job', 'Home Office', 'warning', 'Skilled Workers and Sponsors', 'Radar Editorial', '{"Aligns with latest ASHE earnings data.", "Affects new applications and extensions.", "Transitional provisions apply for some existing workers."}'),
('uk-fm-2026', 'United Kingdom', 'UK', '🇬🇧', 'Family Visa', 'Family', 'Appendix FM income requirement updated', 'The Minimum Income Requirement (MIR) for family visas has been reviewed and adjusted.', 'The minimum income requirement for sponsoring a spouse or partner under Appendix FM has been adjusted in line with the government''s review of family migration policies, impacting how sponsors prove financial capability.', 'Previous baseline MIR applied without recent inflation adjustments.', 'Adjusted MIR baseline aligned with current economic reviews.', '2026-04-11', '2026-03-05', 'https://www.gov.uk/uk-family-visa/proof-income', 'Home Office', 'warning', 'British citizens/settled persons sponsoring partners', 'Radar Editorial', '{"MIR threshold adjusted.", "Savings calculations remain complex.", "Aims to ensure families are self-sufficient."}');
